fn test_input_expression_save_preserves_value_and_secret() -> Result<(), Box<dyn std::error::Error>> {
    let yaml = "version: velvet-ballistics/v1\nname: input_finish\nwhen:\n  manual: {}\ninputs:\n  count: number\nsteps:\n  - id: save\n    save:\n      output: saved\n      value: '$input.count'\n  - id: done\n    finish:\n      result: saved\n";

    let workflow = compile(yaml)?;

    let slots = workflow.input_slots();
    if slots.len() != 1 {
        return Err(format!("expected 1 input slot, got {}", slots.len()));
    }
    if slots[0].slot != SlotIdx::new(1) {
        return Err(format!("slot index mismatch: {:?}", slots[0].slot));
    }
    if slots[0].kind != InputSlotKind::I64 {
        return Err(format!("slot kind mismatch: {:?}", slots[0].kind));
    }

    if workflow.node_count() != 2 {
        return Err(format!("expected 2 nodes, got {}", workflow.node_count()));
    }

    let node0 = workflow.node(vb_core::StepIdx::new(0)).ok_or("node 0 missing")?;
    match &node0.kind {
        EvalExpr { expr } => {
            if *expr != ExprIdx::new(0) {
                return Err(format!("expr index mismatch: {:?}", expr));
            }
        }
        _ => return Err("node 0 should be EvalExpr".into()),
    }
    if node0.output != Some(SlotIdx::new(0)) {
        return Err(format!("node 0 output mismatch: {:?}", node0.output));
    }
    if node0.next != Some(vb_core::StepIdx::new(1)) {
        return Err(format!("node 0 next mismatch: {:?}", node0.next));
    }

    let expr = workflow.expression(ExprIdx::new(0)).ok_or("expr 0 missing")?;
    if expr.ops.as_ref() != &[vb_core::ExprOp::LoadSlot(SlotIdx::new(1))] {
        return Err(format!("expr ops mismatch: {:?}", expr.ops));
    }

    let node1 = workflow.node(vb_core::StepIdx::new(1)).ok_or("node 1 missing")?;
    match &node1.kind {
        Finish { result } => {
            if *result != SlotIdx::new(0) {
                return Err(format!("finish result mismatch: {:?}", result));
            }
        }
        _ => return Err("node 1 should be Finish".into()),
    }
    if node1.next != None {
        return Err(format!("node 1 next should be None: {:?}", node1.next));
    }

    for value in [i64::MIN, -1, 0, 42, i64::MAX] {
        let signal = run(&workflow, &[value])?;
        if signal != EngineSignal::Finished(SlotValue::I64(value), Taint::Secret) {
            return Err(format!("signal mismatch for {}: {:?}", value, signal));
        }
    }

    Ok(())
}
